"""RoboPaint limited-mode controller and executed trajectory record.
Actions are composed around the episode's live proprioceptive pose; never resets.
"""
import sys, json
import numpy as np
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot

DOWN = np.array([0., 1., 0., 0.])

def pose(x, y, z, q=DOWN):
    return [float(x), float(y), float(z), *map(float, q)]

def connect():
    return Robot()

def send_ee(r, points, dt=0.05, note=''):
    return r.submit('ee_pose', np.asarray(points, dtype=np.float32), dt=dt,
                    video='both', note=note)

def save(res, tag):
    res.save('/app/output/' + tag)

def observe(r, tag, cameras=None):
    cams = cameras or ['canvas_cam', 'scene_cam', 'side_cam', 'practice_cam']
    o = r.get_obs(cameras=cams, depth=True, video='none')
    from PIL import Image
    for cam, img in o.last.items():
        Image.fromarray(img).save('/app/output/' + tag + '_' + cam + '.png')
    return o

def do_lift(r):
    o = r.get_obs(video='none'); now = np.asarray(o.meta['proprio']['now'], float)
    x,y,z = now[7:10]
    res = send_ee(r, [pose(x,y,z+dz) for dz in [.04,.08,.12,.16]], .2,
                  'lift brush vertically to clear cameras')
    save(res,'lift'); return res

def do_clear_view(r):
    o = r.get_obs(video='none'); now = np.asarray(o.meta['proprio']['now'], float)
    p0 = now[7:10]; q = now[10:14]
    goal = np.array([-.25,.28,.28]);
    points = [np.r_[p0 + (goal-p0)*i/5, q] for i in range(1,6)]
    res = send_ee(r, points, .5, 'move elevated brush outside canvas camera view')
    save(res,'clear_view')
    o=observe(r,'clear_view')
    print(json.dumps({'meta':res.meta,'pose':o.meta['proprio']['now'][7:14],
                      'time_left_s':o.meta['time_left_s']},indent=2))

if __name__ == '__main__':
    r=connect()
    if len(sys.argv)>1 and sys.argv[1]=='lift': do_lift(r)
    elif len(sys.argv)>1 and sys.argv[1]=='clear': do_clear_view(r)
    else: print('usage: gen.py {lift|clear}')
